    let other_dm = DvInfo::new(1, 43, 0, 58, 0, 0, dm).unwrap();
    for other in [other_k, other_b, other_dm, terminator()] {
        assert_ne!(other, r);
        assert_ne!(other.as_ref(), r.as_ref());
